
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_mpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_mpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.304483389254586e+00, -4.222825285596806e+00, -4.108519632844654e+00, -3.950424128813905e+00, -3.735518904057911e+00, -3.450596776080427e+00, -3.086187626049958e+00, -2.643500001607826e+00, -2.142863007191091e+00, -1.621872274529888e+00, -1.098391325261986e+00, -7.103265668162687e-01, -6.021735144446910e-01, -5.017618566551076e-01, -3.720403158746848e-01, -2.462118058582456e-01, -1.364340439975234e-01, -4.960013860738195e-02, -1.073137269020965e-02, -1.206508456603246e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


